SELECT round_id 
FROM round 
WHERE place_id = #{place_id}

SELECT DISTINCT w.work_id,w.work_title,w.work_poster_url FROM work w
JOIN round r ON w.work_id = r.work_id
WHERE r.place_id = #{place_id}

SELECT * FROM round 
WHERE work_id = #{work_id} 
  AND place_id = #{place_id}
ORDER BY round_date ASC, round_start_time ASC
